import { BASE as B } from '@valtier/ds/lib/base';

const m = (p: string) => `${B}/media/${p}`;

export const hero = {
  name: 'Nico Valtier',
  /** Background marquee words (top row runs left, bottom row runs right). */
  words: ['Nico', 'Valtier'],
  storyCopy:
    'From the river flats of Northmark to the cover of the season preview. Every move Nico makes carries intention, style, and a story you don’t see on the field.',
  cardCopy:
    'The 2019 first-round pick out of Lakeshore State who rewrote the record books — the rookie card that marked the start of a generational career.',
  /** WebGL depth portrait. `lens` is the sunglasses region in image UV (0–1). */
  portrait: {
    diffuse: m('hero/portrait.webp'),
    depth: m('hero/portrait-depth.webp'),
    lens: m('hero/portrait-lens.webp'),
    still: m('hero/portrait.webp'),
    width: 1600,
    height: 1151,
    /** Lens centre in image UV (x, y from the top): the reflected video is centred here. */
    lensCenter: [0.4778, 0.2876] as [number, number],
  },
  /** Footage reflected in the lenses (and shown full-screen at the start of the intro). */
  video: { desktop: m('hero.mp4'), phone: m('hero-phone.mp4'), poster: m('hero-poster.webp') },
};

