export type PartnerArt =
  | { kind: 'depth'; src: string; depth: string; aspect: number; width: string; alt: string }
  | { kind: 'pair'; front: { src: string; alt: string }; back: { src: string; alt: string } }
  | { kind: 'cutout'; src: string; alt: string; scale?: number; y?: string };

export interface Partnership { name: string; description: string; art: PartnerArt }

